from collections import deque
def comps(g,val):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=val or seen[r][c]: continue
            q=deque([(r,c)]); seen[r][c]=True; cells=[(r,c)]
            while q:
                a,b=q.popleft()
                for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and g[x][y]==val and not seen[x][y]:
                        seen[x][y]=True;q.append((x,y));cells.append((x,y))
            out.append(cells)
    return out
# in demo: components of 8s vs changed cells

def solve(g):
    H,W=len(g),len(g[0])
    def cc(vals):
        seen=[[False]*W for _ in range(H)]; out=[]
        for r in range(H):
            for c in range(W):
                if g[r][c]==vals or seen[r][c]: continue
                q=deque([(r,c)]); seen[r][c]=True; cells=[(r,c)]
                while q:
                    a,b=q.popleft()
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==vals and not seen[x][y]:
                            seen[x][y]=True;q.append((x,y));cells.append((x,y))
                out.append(cells)
        return out
    # zero components not touching edge -> border becomes 8
    res=[row[:] for row in g]
    for comp in cc(0):
        rs=[r for r,_ in comp]; cs=[c for _,c in comp]
        top=min(rs); bot=max(rs); left=min(cs); right=max(cs)
        if top==0 or bot==H-1 or left==0 or right==W-1: continue
        # check rect: all zeros in bbox, and no 0 outside
        ok=all((top<=r<=bot and left<=c<=right) for r,c in comp)
        # also require comp fills bbox fully? maybe just outline all-zero rects
        if ok and (bot-top)>=1 and (right-left)>=1:
            for r in range(top,bot+1):
                for c in range(left,right+1):
                    if top<=r<=bot and left<=c<=right:
                        res[r][c]=8 if (r in (top,bot) or c in (left,right)) else res[r][c]
    return res
